      en: ["12th-14th century", "Anjou", "Loire Valley", "Fortress"],
      es: ["Siglos XII-XIV", "Anjou", "Valle del Loira", "Fortaleza"],
      pt: ["Séculos XII-XIV", "Anjou", "Vale do Loire", "Fortaleza"],
      fr: ["XIIe-XIVe siècle", "Anjou", "Vallée de la Loire", "Forteresse"],
